(()=>{const id='calendar-compact-overrides';if(document.getElementById(id))return;const s=document.createElement('style');s.id=id;s.textContent=`
/* Calendário compacto: mais datas visíveis e navegação mais rápida. */
.calendar-months>.sticky{padding:.35rem .5rem!important;gap:.4rem!important;border-radius:.65rem!important}
.calendar-view-switch{gap:.25rem!important;padding:.25rem!important;border-radius:.8rem!important}
.calendar-view-btn{min-height:34px!important;padding:.42rem .72rem!important;border-radius:.62rem!important;font-size:10px!important;gap:.35rem!important}

.calendar-months.calendar-mobile-list{gap:.7rem!important}
.calendar-months.calendar-mobile-list .calendar-month-card{padding:.62rem!important}
.calendar-months.calendar-mobile-list .calendar-month-grid{gap:.28rem!important}
.calendar-months.calendar-mobile-list .calendar-day-card{min-height:0!important;height:auto!important;padding:.4rem .5rem!important;gap:.25rem!important;border-radius:.62rem!important}
.calendar-months.calendar-mobile-list .calendar-day-number{font-size:11px!important}
.calendar-months.calendar-mobile-list .calendar-day-name-mobile{font-size:8px!important}
.calendar-months.calendar-mobile-list .calendar-shift{grid-template-columns:3.8rem minmax(0,1fr)!important;gap:.35rem!important;padding:.28rem .4rem!important;border-radius:.42rem!important;font-size:9.5px!important;line-height:1.18!important}
.calendar-months.calendar-mobile-list .calendar-shift-period{font-size:8.5px!important;padding-top:0!important}
.calendar-months.calendar-mobile-list .calendar-shift-text{font-size:9.5px!important;line-height:1.18!important}

.calendar-months.calendar-mobile-grid .calendar-month-card{padding:.55rem!important}
.calendar-months.calendar-mobile-grid .calendar-month-grid{gap:.35rem!important}
.calendar-months.calendar-mobile-grid .calendar-day-card{min-height:104px!important;padding:.4rem!important}
.calendar-months.calendar-mobile-grid .calendar-empty{min-height:104px!important}

@media(max-width:767px){
.calendar-months>.sticky>div:first-child span:last-child{display:none!important}
.calendar-months.calendar-mobile-grid .calendar-empty{min-height:70px!important}
.calendar-months.calendar-mobile-grid .calendar-day-card{min-height:70px!important;height:70px!important;padding:.18rem!important;gap:.12rem!important}
.calendar-months.calendar-mobile-grid .calendar-day-number{font-size:9px!important}
.calendar-months.calendar-mobile-grid .calendar-shift{padding:.1rem .14rem!important;font-size:6px!important;gap:.08rem!important}
.calendar-months.calendar-mobile-grid .calendar-shift-period,.calendar-months.calendar-mobile-grid .calendar-shift-text{font-size:6px!important}
}
`;document.head.appendChild(s)})();

(()=>{const id='mobile-header-spacing-20260831';if(document.getElementById(id))return;const s=document.createElement('style');s.id=id;s.textContent=`
@media (max-width:1023px){
  #saudacao-aluno{margin-bottom:6px!important;}
  #aluno-logado-badge{line-height:1.12!important;margin-bottom:0!important;}
  #proxima-atividade-badge{margin-top:17px!important;padding:7px 11px!important;display:inline-flex!important;align-items:center!important;border-radius:10px!important;max-width:max-content!important;}
  #mobile-nav-menu,#mobile-footer-menu{display:none!important;}

  #mobile-menu-stable{position:fixed;inset:0;z-index:9999;display:none;}
  #mobile-menu-stable.is-open{display:block;}
  #mobile-menu-stable .mms-backdrop{position:absolute;inset:0;background:rgba(2,4,10,.56);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);}
  #mobile-menu-stable .mms-sheet{position:absolute;left:18px;right:18px;top:calc(env(safe-area-inset-top) + 76px);padding:12px;border-radius:24px;border:1px solid rgba(96,165,250,.16);background:linear-gradient(155deg,rgba(16,20,33,.985),rgba(6,8,15,.985));box-shadow:0 24px 80px -28px rgba(37,99,235,.48),0 30px 80px -34px rgba(0,0,0,.98),inset 0 1px 0 rgba(255,255,255,.05);overflow:hidden;}
  #mobile-menu-stable .mms-sheet::before{content:"";position:absolute;left:14%;right:14%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(96,165,250,.8),rgba(99,102,241,.78),transparent);}
  #mobile-menu-stable .mms-head{display:flex;align-items:center;justify-content:space-between;padding:5px 5px 10px 7px;}
  #mobile-menu-stable .mms-kicker{font-size:9px;line-height:1;text-transform:uppercase;letter-spacing:.18em;font-weight:800;color:#60a5fa;margin-bottom:4px;}
  #mobile-menu-stable .mms-title{font-family:'Outfit',sans-serif;font-size:16px;line-height:1.1;font-weight:800;color:#f8fafc;letter-spacing:-.02em;}
  #mobile-menu-stable .mms-close{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:rgba(255,255,255,.045);border:1px solid rgba(148,163,184,.12);color:#a1a1aa;}
  #mobile-menu-stable .mms-close svg{width:17px;height:17px;}
  #mobile-menu-stable .mms-list{display:flex;flex-direction:column;gap:5px;}
  #mobile-menu-stable .mms-item{width:100%;min-height:47px;display:flex;align-items:center;gap:12px;padding:0 12px;border-radius:14px;border:1px solid transparent;background:transparent;color:#a1a1aa;font-family:'Outfit',sans-serif;font-size:13px;font-weight:750;text-align:left;transition:background .18s ease,border-color .18s ease,color .18s ease,transform .12s ease;}
  #mobile-menu-stable .mms-item:active{transform:scale(.992);}
  #mobile-menu-stable .mms-item:hover{background:rgba(255,255,255,.035);color:#e4e4e7;}
  #mobile-menu-stable .mms-item.is-active{color:#fff;background:linear-gradient(100deg,#2563eb 0%,#3b82f6 38%,#4f46e5 72%,#6d28d9 100%);border-color:rgba(129,140,248,.38);box-shadow:0 12px 28px -18px rgba(59,130,246,.9),inset 0 1px 0 rgba(255,255,255,.16);}
  #mobile-menu-stable .mms-ico{width:34px;height:34px;flex:0 0 34px;display:grid;place-items:center;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid rgba(148,163,184,.08);color:#8b93a7;}
  #mobile-menu-stable .mms-item.is-active .mms-ico{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.12);color:#fff;}
  #mobile-menu-stable .mms-ico svg{width:18px;height:18px;}
  #mobile-menu-stable .mms-chevron{margin-left:auto;width:15px;height:15px;opacity:.45;}
  #mobile-menu-stable .mms-item.is-active .mms-chevron{opacity:.85;}
  #mobile-menu-stable .mms-sep{height:1px;background:rgba(148,163,184,.09);margin:5px 4px;}

  html:not(.dark) #mobile-menu-stable .mms-backdrop{background:rgba(226,232,240,.5);}
  html:not(.dark) #mobile-menu-stable .mms-sheet{background:linear-gradient(155deg,rgba(255,255,255,.995),rgba(248,250,252,.985));border-color:rgba(59,130,246,.15);}
  html:not(.dark) #mobile-menu-stable .mms-title{color:#111827;}
  html:not(.dark) #mobile-menu-stable .mms-item{color:#64748b;}
  html:not(.dark) #mobile-menu-stable .mms-item:hover{background:rgba(15,23,42,.035);color:#0f172a;}
  html:not(.dark) #mobile-menu-stable .mms-ico{background:rgba(15,23,42,.025);border-color:rgba(15,23,42,.06);color:#64748b;}
}
`;document.head.appendChild(s)})();

(()=>{
  const ico={
    hoje:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M3 12l9-9 9 9M5 10v10h14V10M9 20v-6h6v6"/></svg>',
    ind:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M20 21a8 8 0 0 0-16 0M12 13a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z"/></svg>',
    geral:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7" d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM22 21v-2a4 4 0 0 1 3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
    atividade:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>',
    seminarios:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/></svg>',
    calendario:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v15H3V6a2 2 0 0 1 2-2Z"/></svg>',
    recados:'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v8Z"/></svg>'
  };
  const chev='<svg class="mms-chevron" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m9 18 6-6-6-6"/></svg>';
  const item=(modo,label)=>`<button class="mms-item" data-modo="${modo}"><span class="mms-ico">${ico[modo]}</span><span>${label}</span>${chev}</button>`;
  const setup=()=>{
    if(window.innerWidth>=1024) return;
    if(!document.getElementById('mobile-menu-stable')){
      const root=document.createElement('div');
      root.id='mobile-menu-stable';
      root.innerHTML=`<div class="mms-backdrop"></div><div class="mms-sheet"><div class="mms-head"><div><div class="mms-kicker">Navegação</div><div class="mms-title">Menu principal</div></div><button class="mms-close" type="button" aria-label="Fechar menu"><svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="mms-list">${item('hoje','Hoje')}${item('ind','Meu Trio')}${item('geral','Todos os Trios')}<div class="mms-sep"></div>${item('atividade','Atividades')}${item('seminarios','Seminários')}${item('calendario','Calendário')}${item('recados','Recados e Avisos')}</div></div>`;
      document.body.appendChild(root);
      const marcarAtivo=()=>{const atual=window.modoVisualizacao||'hoje';root.querySelectorAll('[data-modo]').forEach(b=>b.classList.toggle('is-active',b.dataset.modo===atual));};
      const close=()=>{root.classList.remove('is-open');document.documentElement.style.overflow='';};
      root.querySelector('.mms-backdrop').addEventListener('click',close);
      root.querySelector('.mms-close').addEventListener('click',close);
      root.querySelectorAll('[data-modo]').forEach(btn=>btn.addEventListener('click',()=>{const modo=btn.getAttribute('data-modo');close();setTimeout(()=>window.alternarModo?.(modo),0);}));
      window.__closeStableMobileMenu=close;
      window.__markStableMobileMenu=marcarAtivo;
    }
    window.toggleMobileMenu=function(){
      const root=document.getElementById('mobile-menu-stable');
      if(!root) return;
      const abrir=!root.classList.contains('is-open');
      if(abrir) window.__markStableMobileMenu?.();
      root.classList.toggle('is-open',abrir);
      document.documentElement.style.overflow=abrir?'hidden':'';
    };
  };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(setup,0),{once:true});
  else setTimeout(setup,0);
  window.addEventListener('resize',()=>{if(window.innerWidth>=1024) window.__closeStableMobileMenu?.();});
})();

(()=>{const id='mobile-top-structural-fix-20260831b';if(document.getElementById(id))return;const s=document.createElement('style');s.id=id;s.textContent=`
@media (max-width:1023px){
  body>aside{
    height:auto!important;
    min-height:0!important;
    max-height:none!important;
    padding:calc(env(safe-area-inset-top) + 14px) 16px 14px!important;
    display:block!important;
  }
  body>aside>div:first-child{
    display:flex!important;
    flex-direction:column!important;
    gap:14px!important;
    height:auto!important;
    min-height:0!important;
  }
  body>aside>div:first-child>div:first-child{
    display:flex!important;
    align-items:center!important;
    justify-content:space-between!important;
    gap:12px!important;
    min-height:0!important;
    height:auto!important;
  }
  body>aside>div:first-child>div:first-child>div:first-child{
    display:flex!important;
    align-items:center!important;
    gap:12px!important;
    min-width:0!important;
    flex:1 1 auto!important;
  }
  body>aside>div:first-child>div:first-child>div:first-child>div:first-child{
    width:52px!important;height:52px!important;min-width:52px!important;flex:0 0 52px!important;border-radius:16px!important;
  }
  body>aside>div:first-child>div:first-child>div:first-child>div:nth-child(2){
    display:block!important;
    min-width:0!important;
    flex:1 1 auto!important;
    overflow:visible!important;
  }
  #saudacao-aluno{
    display:block!important;
    visibility:visible!important;
    opacity:1!important;
    margin:0 0 3px!important;
    font-size:10px!important;
    line-height:1.15!important;
    letter-spacing:.15em!important;
  }
  #aluno-logado-badge{
    display:block!important;
    visibility:visible!important;
    opacity:1!important;
    margin:0!important;
    font-size:20px!important;
    line-height:1.08!important;
    white-space:nowrap!important;
    overflow:hidden!important;
    text-overflow:ellipsis!important;
  }
  #proxima-atividade-badge{
    display:inline-flex!important;
    visibility:visible!important;
    opacity:1!important;
    margin-top:9px!important;
    padding:6px 10px!important;
    max-width:min(250px,62vw)!important;
    font-size:10px!important;
    line-height:1.1!important;
    white-space:nowrap!important;
    overflow:hidden!important;
    text-overflow:ellipsis!important;
  }
  body>aside button[onclick="toggleMobileMenu()"]{
    width:52px!important;height:52px!important;min-width:52px!important;flex:0 0 52px!important;padding:0!important;border-radius:16px!important;
    display:inline-flex!important;align-items:center!important;justify-content:center!important;
  }
  body>aside>div:first-child>.mt-3{
    margin-top:0!important;
    position:relative!important;
    inset:auto!important;
    width:100%!important;
    box-sizing:border-box!important;
  }
}
`;document.head.appendChild(s)})();
